import React, { useState } from 'react';
import Modal from 'react-modal';
import styled from 'styled-components';

// Grid container styling
const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);  // 4 columns grid layout
  gap: 20px;
  margin-top: 20px;
`;

// Each equipment item card styling
const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 15px;
  background-color: ${({ isSelected }) => (isSelected ? '#f0f8ff' : '#fff')};
  text-align: center;
  cursor: pointer;
  transition: box-shadow 0.3s ease, transform 0.3s ease;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
    transform: scale(1.02);
  }
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 180px;
  object-fit: cover;
  border-radius: 8px;
  margin-bottom: 10px;
`;

const ItemName = styled.h3`
  margin: 5px 0;
  font-size: 1.1rem;
  color: #333;
`;

const ItemPrice = styled.p`
  font-size: 1rem;
  color: #4caf50;
  font-weight: bold;
  margin: 5px 0;
`;

const ModalButton = styled.button`
  padding: 10px;
  border-radius: 5px;
  border: none;
  background-color: #007bff;
  color: white;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #0056b3;
  }
`;

const Equipment = ({ equipment, onAddToSelection, selectedItems = [] }) => {
  const [modalItem, setModalItem] = useState(null);

  const openModal = (item) => setModalItem(item);
  const closeModal = () => setModalItem(null);

  // Check if item is selected, defaulting selectedItems to an empty array to avoid undefined error
  const isSelected = (item) =>
    (selectedItems || []).some((selected) => selected.id === item.id);

  const handleSelectionToggle = (item) => {
    if (isSelected(item)) {
      // If item is already in selection, remove it
      onAddToSelection(item, true);
    } else {
      // Otherwise, add it to selection
      onAddToSelection(item, false);
    }
  };

  return (
    <>
      {/* Grid layout for the equipment items */}
      <EquipmentGrid>
        {equipment.map((item) => (
          <EquipmentItem
            key={item.id}
            isSelected={isSelected(item)}
            onClick={() => openModal(item)}
          >
            <EquipmentImage src={item.image_url} alt={item.name} />
            <ItemName>{item.name}</ItemName>
            <p>Brand: {item.brand}</p>
            <ItemPrice>${item.price}</ItemPrice>
          </EquipmentItem>
        ))}
      </EquipmentGrid>

      {/* Modal for displaying equipment details */}
      {modalItem && (
        <Modal
          isOpen={!!modalItem}
          onRequestClose={closeModal}
          style={{
            content: {
              maxWidth: '500px',
              margin: 'auto',
              padding: '20px',
              borderRadius: '10px',
            },
          }}
        >
          <div style={{ textAlign: 'center' }}>
            <h2>{modalItem.name}</h2>
            <img
              src={modalItem.image_url}
              alt={modalItem.name}
              style={{ maxHeight: '300px', borderRadius: '8px', marginBottom: '20px' }}
            />
            <p><strong>Brand:</strong> {modalItem.brand}</p>
            <p><strong>Price:</strong> ${modalItem.price}</p>

            {/* Display Details */}
            {modalItem.details && Array.isArray(modalItem.details) && modalItem.details.length > 0 ? (
              <div>
                <h4>Details:</h4>
                <ul>
                  {modalItem.details.map((detail, index) => (
                    <li key={index}>{detail}</li>
                  ))}
                </ul>
              </div>
            ) : (
              <p><strong>Details:</strong> {typeof modalItem.details === 'string' ? modalItem.details : 'No details available'}</p>
            )}

            {/* Display Tech Specs */}
            {modalItem.tech_specs && Object.keys(modalItem.tech_specs).length > 0 && (
              <div>
                <h4>Tech Specs:</h4>
                <ul>
                  {Object.entries(modalItem.tech_specs).map(([key, value], index) => (
                    <li key={index}><strong>{key}:</strong> {value}</li>
                  ))}
                </ul>
              </div>
            )}

            {modalItem.link && (
              <div style={{ marginTop: '10px' }}>
                <a href={modalItem.link} target="_blank" rel="noopener noreferrer">
                  View Product Page
                </a>
              </div>
            )}

            <ModalButton onClick={() => handleSelectionToggle(modalItem)}>
              {isSelected(modalItem) ? 'Remove from Selection' : 'Add to Selection'}
            </ModalButton>
            <ModalButton onClick={closeModal} style={{ backgroundColor: '#6c757d', marginLeft: '10px' }}>
              Close
            </ModalButton>
          </div>
        </Modal>
      )}
    </>
  );
};

export default Equipment;
